-- One-off backfill for rows that got a section before the mir-from-section triggers existed.
-- NOT run by the app. Needs an explicit approval before it runs on production. Idempotent (a second run changes nothing).
-- Same rules as the triggers (src/signup/mir-from-section.ts, MIR_FROM_SECTION_BACKFILL):
--   1-2. signups.mir_code: filled from the section (published, else draft) only when empty; a different home МИР stays.
--   3-4. partner_people.designation_mir: unnumbered, not withdrawn rows follow their own section (published, else draft),
--        else the covering volunteer (covered_by_signup_id: number МИР once numbered, else section МИР).
--        Numbered rows never move. Each change writes one signup_audit line (field 'mir').

INSERT INTO signup_audit (id, signup_id, actor, field, before_text, after_text, created_at)
SELECT lower(hex(randomblob(16))), s.id, 'system (МИР от секцията)', 'mir', '—', (CASE WHEN TRIM(COALESCE(s.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(s.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(s.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(s.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(s.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(s.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(s.draft_section, '')), 1, 2) ELSE '' END) END), strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
FROM signups s WHERE TRIM(COALESCE(s.mir_code, '')) = '' AND (CASE WHEN TRIM(COALESCE(s.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(s.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(s.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(s.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(s.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(s.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(s.draft_section, '')), 1, 2) ELSE '' END) END) != '';

UPDATE signups SET mir_code = (CASE WHEN TRIM(COALESCE(signups.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(signups.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(signups.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(signups.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(signups.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(signups.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(signups.draft_section, '')), 1, 2) ELSE '' END) END)
WHERE TRIM(COALESCE(mir_code, '')) = '' AND (CASE WHEN TRIM(COALESCE(signups.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(signups.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(signups.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(signups.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(signups.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(signups.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(signups.draft_section, '')), 1, 2) ELSE '' END) END) != '';

INSERT INTO signup_audit (id, signup_id, actor, field, before_text, after_text, created_at)
SELECT lower(hex(randomblob(16))), p.id, 'system (МИР от секцията)', 'mir', COALESCE(NULLIF(COALESCE(p.designation_mir, ''), ''), '—'), COALESCE(NULLIF((CASE WHEN TRIM(COALESCE(p.section_published, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(p.section_published, ''))) >= 8 AND substr(TRIM(COALESCE(p.section_published, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(p.section_published, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(p.section_draft, ''))) >= 8 AND substr(TRIM(COALESCE(p.section_draft, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(p.section_draft, '')), 1, 2) ELSE '' END) END), ''), (SELECT (CASE WHEN cs.designation_number IS NOT NULL AND COALESCE(cs.designation_mir, '') != '' THEN cs.designation_mir ELSE (CASE WHEN TRIM(COALESCE(cs.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(cs.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(cs.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) ELSE '' END) END) END) FROM signups cs WHERE cs.id = p.covered_by_signup_id), ''), strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
FROM partner_people p WHERE p.designation_number IS NULL AND p.withdrawn_at IS NULL AND COALESCE(NULLIF((CASE WHEN TRIM(COALESCE(p.section_published, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(p.section_published, ''))) >= 8 AND substr(TRIM(COALESCE(p.section_published, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(p.section_published, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(p.section_draft, ''))) >= 8 AND substr(TRIM(COALESCE(p.section_draft, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(p.section_draft, '')), 1, 2) ELSE '' END) END), ''), (SELECT (CASE WHEN cs.designation_number IS NOT NULL AND COALESCE(cs.designation_mir, '') != '' THEN cs.designation_mir ELSE (CASE WHEN TRIM(COALESCE(cs.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(cs.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(cs.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) ELSE '' END) END) END) FROM signups cs WHERE cs.id = p.covered_by_signup_id), '') != '' AND COALESCE(p.designation_mir, '') != COALESCE(NULLIF((CASE WHEN TRIM(COALESCE(p.section_published, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(p.section_published, ''))) >= 8 AND substr(TRIM(COALESCE(p.section_published, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(p.section_published, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(p.section_draft, ''))) >= 8 AND substr(TRIM(COALESCE(p.section_draft, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(p.section_draft, '')), 1, 2) ELSE '' END) END), ''), (SELECT (CASE WHEN cs.designation_number IS NOT NULL AND COALESCE(cs.designation_mir, '') != '' THEN cs.designation_mir ELSE (CASE WHEN TRIM(COALESCE(cs.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(cs.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(cs.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) ELSE '' END) END) END) FROM signups cs WHERE cs.id = p.covered_by_signup_id), '');

UPDATE partner_people SET designation_mir = COALESCE(NULLIF((CASE WHEN TRIM(COALESCE(partner_people.section_published, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(partner_people.section_published, ''))) >= 8 AND substr(TRIM(COALESCE(partner_people.section_published, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(partner_people.section_published, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(partner_people.section_draft, ''))) >= 8 AND substr(TRIM(COALESCE(partner_people.section_draft, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(partner_people.section_draft, '')), 1, 2) ELSE '' END) END), ''), (SELECT (CASE WHEN cs.designation_number IS NOT NULL AND COALESCE(cs.designation_mir, '') != '' THEN cs.designation_mir ELSE (CASE WHEN TRIM(COALESCE(cs.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(cs.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(cs.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) ELSE '' END) END) END) FROM signups cs WHERE cs.id = partner_people.covered_by_signup_id), '')
WHERE partner_people.designation_number IS NULL AND partner_people.withdrawn_at IS NULL AND COALESCE(NULLIF((CASE WHEN TRIM(COALESCE(partner_people.section_published, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(partner_people.section_published, ''))) >= 8 AND substr(TRIM(COALESCE(partner_people.section_published, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(partner_people.section_published, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(partner_people.section_draft, ''))) >= 8 AND substr(TRIM(COALESCE(partner_people.section_draft, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(partner_people.section_draft, '')), 1, 2) ELSE '' END) END), ''), (SELECT (CASE WHEN cs.designation_number IS NOT NULL AND COALESCE(cs.designation_mir, '') != '' THEN cs.designation_mir ELSE (CASE WHEN TRIM(COALESCE(cs.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(cs.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(cs.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) ELSE '' END) END) END) FROM signups cs WHERE cs.id = partner_people.covered_by_signup_id), '') != '' AND COALESCE(partner_people.designation_mir, '') != COALESCE(NULLIF((CASE WHEN TRIM(COALESCE(partner_people.section_published, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(partner_people.section_published, ''))) >= 8 AND substr(TRIM(COALESCE(partner_people.section_published, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(partner_people.section_published, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(partner_people.section_draft, ''))) >= 8 AND substr(TRIM(COALESCE(partner_people.section_draft, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(partner_people.section_draft, '')), 1, 2) ELSE '' END) END), ''), (SELECT (CASE WHEN cs.designation_number IS NOT NULL AND COALESCE(cs.designation_mir, '') != '' THEN cs.designation_mir ELSE (CASE WHEN TRIM(COALESCE(cs.published_section, '')) != '' THEN (CASE WHEN length(TRIM(COALESCE(cs.published_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.published_section, '')), 1, 2) ELSE '' END) ELSE (CASE WHEN length(TRIM(COALESCE(cs.draft_section, ''))) >= 8 AND substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) GLOB '[0-9][0-9]' THEN substr(TRIM(COALESCE(cs.draft_section, '')), 1, 2) ELSE '' END) END) END) FROM signups cs WHERE cs.id = partner_people.covered_by_signup_id), '');
